output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "Shoppers are obliged to take the entrance cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_item_pickup_without_cart",
    "text": "It is forbidden to pick up shelf items unless the shopper currently has a cart.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "cartless",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "It is forbidden to carry groceries by hand rather than keeping them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "return_cart_after_loading",
    "text": "After placing any required item in the cart, the shopper is obliged to return the cart to the return bay at (0,1) before the trip ends.",
    "abstraction": {
      "state_properties": {
        "at_cart_return_bay": "at(0,1)",
        "loaded_cart_context": "hasCart"
      },
      "events": {
        "item_loaded_into_cart": {
          "pre": {
            "and": [
              "loaded_cart_context",
              "PICKUP_ITEM"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "at_cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_loaded_into_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "only_leave_cart_at_return_bay",
    "text": "It is forbidden to leave a cart anywhere except the designated return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "at_designated_return_bay": "at(0,1)",
        "outside_return_bay": {
          "not": "at_designated_return_bay"
        }
      },
      "events": {
        "leave_cart_outside_return_bay": {
          "pre": {
            "and": [
              "outside_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "It is forbidden to go through the store exit while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "at_exit_cell": "at(9,5)"
      },
      "events": {
        "exit_while_with_cart": {
          "pre": {
            "and": [
              "at_exit_cell",
              "with_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_while_with_cart"
    }
  },
  {
    "id": "cart_free_exit_zone",
    "text": "Carts are prohibited in the pedestrian checkout and exit zone on the right side of the store.",
    "abstraction": {
      "state_properties": {
        "pedestrian_exit_zone": {
          "or": [
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_pedestrian_exit_zone": {
          "and": [
            "hasCart",
            "pedestrian_exit_zone"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_pedestrian_exit_zone"
    }
  },
  {
    "id": "turn_back_from_eggs_with_cart",
    "text": "After taking an item from the eggs end-cap at (6,4) with a cart, the shopper is obliged to turn back west from that cell instead of continuing farther east.",
    "abstraction": {
      "state_properties": {
        "at_eggs_endcap_pickup_cell": "at(6,4)",
        "with_cart_at_eggs_endcap": {
          "and": [
            "at_eggs_endcap_pickup_cell",
            "hasCart"
          ]
        }
      },
      "events": {
        "take_eggs_with_cart": {
          "pre": {
            "and": [
              "with_cart_at_eggs_endcap",
              "PICKUP_ITEM"
            ]
          },
          "post": "hasCart"
        },
        "turn_west_from_eggs_endcap": {
          "pre": {
            "and": [
              "with_cart_at_eggs_endcap",
              "W"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_eggs_with_cart",
      "discharge": "turn_west_from_eggs_endcap"
    }
  }
]
